sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   if(newValue!=''){
	g_form.setSectionDisplay('device_details',true);
	g_form.setSectionDisplay('delivery_details',true);
	var ga = new GlideAjax('getAIDetails');
		ga.addParam('sysparm_name', 'getDetails');
		ga.addParam('sysparm_ai_details', newValue);
		ga.getXMLAnswer(displayDetails);
   }
}
function displayDetails(answer){
	var obj = JSON.parse(answer);
	g_form.setValue('u_model', obj.model);
	g_form.setValue('u_device_description',obj.desc);
	g_form.setValue('u_price_9',obj.price);
	g_form.setValue('u_warrenty_expiration',obj.warranty);
   }
